-- Kotoba Quest learning engine: secure answer checking, completion rewards,
-- public-safe leaderboard, achievements, daily quest rewards and expanded course.

create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;

alter table public.user_stats add column if not exists hearts_updated_at timestamptz not null default now();

-- Index the course/lesson traversal and question ordering paths.
create index if not exists lesson_questions_lesson_sort_idx on public.lesson_questions(lesson_id,sort_order);
create index if not exists lessons_unit_sort_idx on public.lessons(unit_id,sort_order);
create index if not exists units_course_sort_idx on public.units(course_id,sort_order);

-- Do not expose correct answers through PostgREST column selection.
revoke select on public.lesson_questions from anon, authenticated;
grant select (id, lesson_id, prompt, prompt_translation, question_type, options, audio_url, sort_order)
  on public.lesson_questions to anon, authenticated;

create or replace function private.check_lesson_answer(p_question_id uuid, p_answer text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  select jsonb_build_object(
    'correct', lower(trim(coalesce(p_answer,''))) = lower(trim(q.answer_key)),
    'correct_answer', q.answer_key,
    'explanation', q.explanation
  ) into v_result
  from public.lesson_questions q
  join public.lessons l on l.id=q.lesson_id
  where q.id=p_question_id and l.is_published=true;
  if v_result is null then raise exception 'QUESTION_NOT_FOUND'; end if;
  return v_result;
end;
$$;

create or replace function private.complete_lesson(p_lesson_id uuid, p_answers jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid(); v_total integer; v_correct integer; v_score integer;
  v_xp integer := 0; v_reward integer; v_was_complete boolean := false;
  v_attempt_id uuid; v_last_date date; v_streak integer;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
  if jsonb_typeof(p_answers) <> 'array' then raise exception 'INVALID_ANSWERS'; end if;
  select count(*)::int,max(l.xp_reward) into v_total,v_reward
  from public.lesson_questions q join public.lessons l on l.id=q.lesson_id
  where q.lesson_id=p_lesson_id and l.is_published=true;
  if v_total=0 then raise exception 'LESSON_NOT_FOUND'; end if;
  if jsonb_array_length(p_answers)<>v_total then raise exception 'INCOMPLETE_LESSON'; end if;
  select count(*)::int into v_correct
  from public.lesson_questions q
  join jsonb_to_recordset(p_answers) as a(question_id uuid,answer text) on a.question_id=q.id
  where q.lesson_id=p_lesson_id and lower(trim(coalesce(a.answer,'')))=lower(trim(q.answer_key));
  if (select count(distinct question_id) from jsonb_to_recordset(p_answers) as a(question_id uuid,answer text))<>v_total then
    raise exception 'DUPLICATE_OR_INVALID_ANSWERS';
  end if;
  v_score:=round((v_correct::numeric/v_total::numeric)*100);
  select coalesce(status='completed',false) into v_was_complete
  from public.user_progress where user_id=v_user and lesson_id=p_lesson_id;
  v_was_complete:=coalesce(v_was_complete,false);
  if v_score>=70 and not v_was_complete then v_xp:=coalesce(v_reward,10); end if;
  insert into public.lesson_attempts(user_id,lesson_id,score,xp_earned,answers)
  values(v_user,p_lesson_id,v_score,v_xp,p_answers) returning id into v_attempt_id;
  insert into public.user_progress(user_id,lesson_id,status,best_score,attempts_count,completed_at,updated_at)
  values(v_user,p_lesson_id,case when v_score>=70 then 'completed' else 'in_progress' end,v_score,1,
    case when v_score>=70 then now() else null end,now())
  on conflict(user_id,lesson_id) do update set
    status=case when public.user_progress.status='completed' or excluded.status='completed' then 'completed' else 'in_progress' end,
    best_score=greatest(public.user_progress.best_score,excluded.best_score),
    attempts_count=public.user_progress.attempts_count+1,
    completed_at=case when public.user_progress.completed_at is not null then public.user_progress.completed_at
      when excluded.status='completed' then now() else null end,
    updated_at=now();
  insert into public.user_stats(user_id) values(v_user) on conflict(user_id) do nothing;
  select last_activity_date,current_streak into v_last_date,v_streak from public.user_stats where user_id=v_user;
  update public.user_stats set
    total_xp=total_xp+v_xp, coins=coins+floor(v_xp/10.0)::bigint, last_activity_date=current_date,
    current_streak=case when v_last_date=current_date then v_streak when v_last_date=current_date-1 then v_streak+1 else 1 end,
    longest_streak=greatest(longest_streak,case when v_last_date=current_date then v_streak when v_last_date=current_date-1 then v_streak+1 else 1 end),
    updated_at=now()
  where user_id=v_user;
  insert into public.user_daily_quests(user_id,quest_id,quest_date)
  select v_user,id,current_date from public.daily_quests where is_published=true
  on conflict(user_id,quest_id,quest_date) do nothing;
  update public.user_daily_quests udq set
    progress_value=least(dq.goal_value,udq.progress_value+case
      when dq.goal_type='complete_lessons' and v_score>=70 then 1
      when dq.goal_type='earn_xp' then v_xp
      when dq.goal_type='correct_answers' then v_correct else 0 end),
    completed_at=case when least(dq.goal_value,udq.progress_value+case
      when dq.goal_type='complete_lessons' and v_score>=70 then 1
      when dq.goal_type='earn_xp' then v_xp
      when dq.goal_type='correct_answers' then v_correct else 0 end)>=dq.goal_value
      then coalesce(udq.completed_at,now()) else udq.completed_at end
  from public.daily_quests dq
  where udq.quest_id=dq.id and udq.user_id=v_user and udq.quest_date=current_date;
  return jsonb_build_object('attempt_id',v_attempt_id,'score',v_score,'correct',v_correct,'total',v_total,
    'passed',v_score>=70,'xp_earned',v_xp,'already_completed',v_was_complete);
end;
$$;

create or replace function private.get_leaderboard()
returns table(display_name text,total_xp bigint,current_streak integer,rank_position bigint)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  return query
  select coalesce(p.display_name,'Aprendiz'),s.total_xp,s.current_streak,
    row_number() over(order by s.total_xp desc,s.current_streak desc)
  from public.user_stats s join public.profiles p on p.id=s.user_id
  order by s.total_xp desc,s.current_streak desc limit 20;
end;
$$;

create or replace function public.check_lesson_answer(p_question_id uuid,p_answer text)
returns jsonb language sql security invoker set search_path=public,pg_temp
as $$ select private.check_lesson_answer(p_question_id,p_answer) $$;
create or replace function public.complete_lesson(p_lesson_id uuid,p_answers jsonb)
returns jsonb language sql security invoker set search_path=public,pg_temp
as $$ select private.complete_lesson(p_lesson_id,p_answers) $$;
create or replace function public.get_leaderboard()
returns table(display_name text,total_xp bigint,current_streak integer,rank_position bigint)
language sql security invoker set search_path=public,pg_temp
as $$ select * from private.get_leaderboard() $$;

revoke all on function private.check_lesson_answer(uuid,text) from public,anon;
revoke all on function private.complete_lesson(uuid,jsonb) from public,anon;
revoke all on function private.get_leaderboard() from public,anon;
grant execute on function private.check_lesson_answer(uuid,text) to authenticated;
grant execute on function private.complete_lesson(uuid,jsonb) to authenticated;
grant execute on function private.get_leaderboard() to authenticated;
revoke all on function public.check_lesson_answer(uuid,text) from public,anon;
revoke all on function public.complete_lesson(uuid,jsonb) from public,anon;
revoke all on function public.get_leaderboard() from public,anon;
grant execute on function public.check_lesson_answer(uuid,text) to authenticated;
grant execute on function public.complete_lesson(uuid,jsonb) to authenticated;
grant execute on function public.get_leaderboard() to authenticated;

insert into public.achievements(slug,title,description,icon,xp_reward,is_published) values
 ('first-lesson','Primeiro passo','Conclua sua primeira lição.','🌸',10,true),
 ('five-lessons','Aprendiz dedicado','Conclua cinco lições.','📘',20,true),
 ('ten-lessons','Estudante constante','Conclua dez lições.','🔥',35,true),
 ('twenty-five-lessons','Explorador do Japão','Conclua as 25 lições da trilha inicial.','⛩️',75,true),
 ('perfect-lesson','Perfeição','Consiga 100% em uma lição.','🏆',15,true),
