on conflict(slug) do update set title=excluded.title,description=excluded.description,icon=excluded.icon,xp_reward=excluded.xp_reward,is_published=true;

create or replace function private.sync_lesson_achievements()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_completed integer;
begin
  if auth.uid() is null or auth.uid()<>new.user_id then return new; end if;
  select count(*)::int into v_completed from public.user_progress where user_id=new.user_id and status='completed';
  insert into public.user_achievements(user_id,achievement_id)
  select new.user_id,a.id from public.achievements a where a.is_published=true and (
    (a.slug='first-lesson' and v_completed>=1) or (a.slug='five-lessons' and v_completed>=5) or
    (a.slug='ten-lessons' and v_completed>=10) or (a.slug='twenty-five-lessons' and v_completed>=25) or
    (a.slug='perfect-lesson' and new.status='completed' and new.best_score=100))
  on conflict(user_id,achievement_id) do nothing;
  return new;
end; $$;

create or replace function private.sync_streak_achievement()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
  if auth.uid() is null or auth.uid()<>new.user_id then return new; end if;
  if new.current_streak>=7 then
    insert into public.user_achievements(user_id,achievement_id)
    select new.user_id,id from public.achievements where slug='seven-day-streak'
    on conflict(user_id,achievement_id) do nothing;
  end if;
  return new;
end; $$;

create or replace function private.reward_daily_quest()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_reward integer;
begin
  if old.completed_at is null and new.completed_at is not null then
    if auth.uid() is null or auth.uid()<>new.user_id then return new; end if;
    select reward_xp into v_reward from public.daily_quests where id=new.quest_id;
    update public.user_stats set total_xp=total_xp+coalesce(v_reward,0),updated_at=now() where user_id=new.user_id;
  end if;
  return new;
end; $$;

drop trigger if exists trg_kotoba_lesson_achievements on public.user_progress;
create trigger trg_kotoba_lesson_achievements after insert or update of status,best_score on public.user_progress
for each row execute function private.sync_lesson_achievements();
drop trigger if exists trg_kotoba_streak_achievement on public.user_stats;
create trigger trg_kotoba_streak_achievement after update of current_streak on public.user_stats
for each row execute function private.sync_streak_achievement();
drop trigger if exists trg_kotoba_daily_quest_reward on public.user_daily_quests;
create trigger trg_kotoba_daily_quest_reward after update of completed_at on public.user_daily_quests
for each row execute function private.reward_daily_quest();
revoke all on function private.sync_lesson_achievements() from public,anon;
revoke all on function private.sync_streak_achievement() from public,anon;
revoke all on function private.reward_daily_quest() from public,anon;

