insert into public.units(course_id,title,description,sort_order)
select '3228b3f6-1cb1-4506-834a-940fcf4eb8a5'::uuid,x.title,x.description,x.sort_order
from seed s cross join lateral jsonb_to_recordset(s.j->'units') as x(title text,description text,sort_order int)
where not exists(select 1 from public.units u where u.course_id='3228b3f6-1cb1-4506-834a-940fcf4eb8a5'::uuid and u.title=x.title);

