rows as (select l.* from seed s cross join lateral jsonb_to_recordset(s.j->'lessons') as l(unit_title text,title text,questions jsonb))
insert into public.lesson_questions(lesson_id,prompt,prompt_translation,question_type,options,answer_key,explanation,sort_order)
select l.id,q.prompt,q.prompt_translation,q.question_type,q.options,q.answer_key,q.explanation,q.sort_order
from rows r join public.units u on u.course_id='3228b3f6-1cb1-4506-834a-940fcf4eb8a5'::uuid and u.title=r.unit_title
join public.lessons l on l.unit_id=u.id and l.title=r.title
cross join lateral jsonb_to_recordset(r.questions) as q(prompt text,prompt_translation text,question_type text,options jsonb,answer_key text,explanation text,sort_order int)
where not exists(select 1 from public.lesson_questions old where old.lesson_id=l.id and old.sort_order=q.sort_order);

-- Award the XP attached to achievements only on the first unlock.
create or replace function private.sync_lesson_achievements()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_completed integer; v_reward integer := 0;
begin
  if auth.uid() is null or auth.uid()<>new.user_id then return new; end if;
  select count(*)::int into v_completed from public.user_progress where user_id=new.user_id and status='completed';
  with unlocked as (
    insert into public.user_achievements(user_id,achievement_id)
    select new.user_id,a.id from public.achievements a where a.is_published=true and (
      (a.slug='first-lesson' and v_completed>=1) or (a.slug='five-lessons' and v_completed>=5) or
      (a.slug='ten-lessons' and v_completed>=10) or (a.slug='twenty-five-lessons' and v_completed>=25) or
      (a.slug='perfect-lesson' and new.status='completed' and new.best_score=100))
    on conflict(user_id,achievement_id) do nothing returning achievement_id
  )
  select coalesce(sum(a.xp_reward),0)::int into v_reward from unlocked u join public.achievements a on a.id=u.achievement_id;
  if v_reward>0 then
    insert into public.user_stats(user_id,total_xp,coins) values(new.user_id,v_reward,floor(v_reward/10.0)::bigint)
    on conflict(user_id) do update set total_xp=public.user_stats.total_xp+excluded.total_xp,
      coins=public.user_stats.coins+excluded.coins,updated_at=now();
  end if;
  return new;
end; $$;

create or replace function private.sync_streak_achievement()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_reward integer := 0;
begin
  if auth.uid() is null or auth.uid()<>new.user_id then return new; end if;
  if new.current_streak>=7 then
    with unlocked as (
      insert into public.user_achievements(user_id,achievement_id)
      select new.user_id,id from public.achievements where slug='seven-day-streak'
      on conflict(user_id,achievement_id) do nothing returning achievement_id
    )
    select coalesce(sum(a.xp_reward),0)::int into v_reward from unlocked u join public.achievements a on a.id=u.achievement_id;
    if v_reward>0 then update public.user_stats set total_xp=total_xp+v_reward,coins=coins+floor(v_reward/10.0)::bigint,updated_at=now() where user_id=new.user_id; end if;
  end if;
  return new;
end; $$;

-- Heart loss and automatic regeneration: one heart every four hours, up to five.
create or replace function private.check_lesson_answer(p_question_id uuid,p_answer text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_user uuid:=auth.uid(); v_answer text; v_explanation text; v_correct boolean;
  v_hearts integer; v_last timestamptz; v_regen integer;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
  select q.answer_key,q.explanation into v_answer,v_explanation
  from public.lesson_questions q join public.lessons l on l.id=q.lesson_id
  where q.id=p_question_id and l.is_published=true;
  if v_answer is null then raise exception 'QUESTION_NOT_FOUND'; end if;
  insert into public.user_stats(user_id) values(v_user) on conflict(user_id) do nothing;
  select hearts,hearts_updated_at into v_hearts,v_last from public.user_stats where user_id=v_user;
  v_regen:=greatest(0,floor(extract(epoch from (now()-v_last))/14400)::int);
  if v_regen>0 then
    v_hearts:=least(5,v_hearts+v_regen);
    update public.user_stats set hearts=v_hearts,hearts_updated_at=case when v_hearts>=5 then now() else v_last+(v_regen*interval '4 hours') end,updated_at=now() where user_id=v_user;
  end if;
  v_correct:=lower(trim(coalesce(p_answer,'')))=lower(trim(v_answer));
  if not v_correct then
    if v_hearts<=0 then raise exception 'NO_HEARTS'; end if;
    v_hearts:=v_hearts-1;
    update public.user_stats set hearts=v_hearts,hearts_updated_at=now(),updated_at=now() where user_id=v_user;
  end if;
  return jsonb_build_object('correct',v_correct,'correct_answer',v_answer,'explanation',v_explanation,'hearts_remaining',v_hearts);
end; $$;
